package com.cpf.batch.agent.internal; import com.cpf.batch.agent.AgentProperties; import java.io.*; import java.nio.file.*; import java.util.zip.*;
public final class LogArchiveService { private final AgentProperties p;public LogArchiveService(AgentProperties p){this.p=p;} public Path collect(String id)throws IOException{var s=p.getServices().values().stream().filter(x->id.equals(x.getServiceId())).findFirst().orElseThrow(()->new SecurityException("unknown service"));Path root=Path.of(s.getLogRoot()).toAbsolutePath().normalize();if(!Files.isDirectory(root))throw new FileNotFoundException("log root");Path work=Path.of(s.getInstallRoot()).toAbsolutePath().normalize().resolve("work");Files.createDirectories(work);Path zip=Files.createTempFile(work,"logs-"+id+"-",".zip");long[] total={0};try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(zip));var walk=Files.walk(root)){walk.filter(Files::isRegularFile).filter(x->x.toString().endsWith(".log")||x.toString().endsWith(".gz")).forEach(x->{try{total[0]+=Files.size(x);if(total[0]>p.getMaxLogArchiveBytes())throw new IOException("archive limit");String e=root.relativize(x).toString().replace('\\','/');if(e.contains(".."))throw new SecurityException("path escape");out.putNextEntry(new ZipEntry(e));Files.copy(x,out);out.closeEntry();}catch(IOException ex){throw new UncheckedIOException(ex);}});}catch(UncheckedIOException e){Files.deleteIfExists(zip);throw e.getCause();}return zip;} }
